begin;
select plan(15);
select has_table('app','room_security_events','room security audit has its own durable table');
select ok((select relrowsecurity from pg_class where oid='app.room_security_events'::regclass),'private audit enables RLS');
select ok(not has_table_privilege('anon','app.room_security_events','select'),'anon cannot read audit');
select ok(not has_table_privilege('authenticated','app.room_security_events','select'),'authenticated Data API cannot read audit');
select ok(not has_table_privilege('authenticated','app.room_security_events','insert'),'browser cannot append audit');
select ok(has_table_privilege('service_role','app.room_security_events','select,insert'),'service can read and append');
select ok(not has_table_privilege('service_role','app.room_security_events','update'),'service cannot rewrite audit');
select ok(not has_table_privilege('service_role','app.room_security_events','delete'),'service cannot delete individual audit events');
select ok(not has_sequence_privilege('authenticated','app.room_security_events_id_seq','usage'),'browser cannot allocate audit IDs');
select hasnt_column('app','room_security_events','payload','no raw payload');
select hasnt_column('app','room_security_events','session_id','no session identity');
insert into auth.users(id,email) values ('f3000000-0000-4000-8000-000000000001','security-sql@example.invalid');
insert into app.campaigns(id,owner_user_id,name) values ('f3000000-0000-4000-8000-000000000002','f3000000-0000-4000-8000-000000000001','SQL audit');
insert into app.rooms(id,campaign_id,owner_user_id,name) values ('f3000000-0000-4000-8000-000000000003','f3000000-0000-4000-8000-000000000002','f3000000-0000-4000-8000-000000000001','SQL audit');
insert into app.participants(id,campaign_id,room_id,user_id,role,display_name) values ('f3000000-0000-4000-8000-000000000004','f3000000-0000-4000-8000-000000000002','f3000000-0000-4000-8000-000000000003','f3000000-0000-4000-8000-000000000001','gm','GM');
insert into app.room_security_events(room_id,participant_id,display_name,type,reason) values ('f3000000-0000-4000-8000-000000000003','f3000000-0000-4000-8000-000000000004','GM','connection.opened','authorized_socket');
select ok((select occurred_at between now() and clock_timestamp() from app.room_security_events where room_id='f3000000-0000-4000-8000-000000000003'),'audit time comes from server');
select is((select scene_version from app.rooms where id='f3000000-0000-4000-8000-000000000003'),0::bigint,'audit leaves gameplay version alone');
select is((select count(*) from app.room_events where room_id='f3000000-0000-4000-8000-000000000003'),0::bigint,'audit leaves gameplay cursor alone');
select throws_ok($$insert into app.room_security_events(room_id,participant_id,display_name,type,reason) values ('f3000000-0000-4000-8000-000000000003','f3000000-0000-4000-8000-000000000099','Invented','participant.joined','guest_join')$$,'23503',null,'nonexistent participant cannot create audit');
select * from finish();
rollback;
